// ============================================================================
// Configuration Helper Functions
// ============================================================================

/**
 * Initialize configuration with defaults for current platform
 */
void guikit_config_init(guikit_config_t* config);

/**
 * Check if RAM bank is available
 */
bool guikit_ram_bank_available(const guikit_config_t* config, uint8_t bank_index);

/**
 * Get total available RAM
 */
uint32_t guikit_get_total_ram(const guikit_config_t* config);

/**
 * Get available RAM in a specific bank
 */
uint32_t guikit_get_bank_ram(const guikit_config_t* config, uint8_t bank_index);

/**
 * Check if SPI expander is available
 */
bool guikit_spi_expander_available(const guikit_config_t* config, uint8_t expander_index);

/**
 * Get total GPIO pins available from expanders
 */
uint16_t guikit_get_total_expander_gpio(const guikit_config_t* config);

/**
 * Calculate framebuffer size based on display config
 */
uint32_t guikit_calculate_framebuffer_size(const display_config_t* display);

/**
 * Validate configuration
 */
bool guikit_config_validate(const guikit_config_t* config);

/**
 * Print configuration summary
 */
void guikit_config_print(const guikit_config_t* config);

// ============================================================================
// Inline Helper Functions
// ============================================================================

static inline bool guikit_has_internal_ram(const guikit_config_t* config) {
    return config->ram.internal_available;
}

static inline bool guikit_has_external_ram(const guikit_config_t* config) {
    return config->ram.total_external > 0;
}

static inline bool guikit_has_spi_expanders(const guikit_config_t* config) {
    return config->spi.expander_count > 0;
}

static inline uint8_t guikit_get_color_bytes(display_color_depth_t depth) {
    return (depth + 7) / 8;  // Round up to nearest byte
}

// ============================================================================
// Configuration Macros
// ============================================================================

// Check if we're running on ESP8266
#define GUIKIT_IS_ESP8266() (PLATFORM_ESP8266)

// Check if we're running on ESP32
#define GUIKIT_IS_ESP32() (PLATFORM_ESP32)

// Get display color bytes from config
#define GUIKIT_DISPLAY_BYTES_PER_PIXEL(config) \
    guikit_get_color_bytes((config)->display.color_depth)

// Calculate framebuffer size
#define GUIKIT_FRAMEBUFFER_SIZE(config) \
    ((config)->display.width * (config)->display.height * \
     GUIKIT_DISPLAY_BYTES_PER_PIXEL(config))

// Check if double buffering is enabled
#define GUIKIT_DOUBLE_BUFFER(config) ((config)->display.double_buffer)

// Check if animation buffer is enabled
#define GUIKIT_ANIMATION_BUFFER(config) ((config)->display.animation_buffer)

// Total buffer size needed
#define GUIKIT_TOTAL_BUFFER_SIZE(config) \
    (GUIKIT_FRAMEBUFFER_SIZE(config) * \
     (GUIKIT_DOUBLE_BUFFER(config) ? 2 : 1) * \
     (GUIKIT_ANIMATION_BUFFER(config) ? 2 : 1))

#endif // GUIKIT_CONFIG_H
